def reclaim_id(lb,body,close):return f'RECLAIM_L{lb}_B{body:g}_C'+('NONE' if close is None else f'{close:g}')

def study_definitions():
    rows=[]
    for cid,kind,anchor in (('PRIMARY__CONTROL','PRIMARY','PRIMARY'),('FREQUENCY__CONTROL','FREQUENCY','FREQUENCY'),('HYBRID__H4_VOL_LE_1.1','VOL_COMPARATOR','PRIMARY')):
        rows.append({'id':cid,'kind':kind,'anchor':anchor,'family':'FROZEN_CONTROL','scope':kind,'feature':None,'cap':None,'availability':False,'body':1.40,'lookback':40 if kind=='PRIMARY' else 20,'distance':.50,'rr':STUDY_RR,'ratio':.60,'close':None,'range':1.50,'regional':False})
    geometries=[(l,b,c,True) for l in RECLAIM_LB for b in RECLAIM_BODY for c in RECLAIM_CLOSE]+[(20,.75,.65,False)]
    for lb,body,close,regional in geometries:
        cid=reclaim_id(lb,body,close)
        d={'id':cid,'kind':'RECLAIM','anchor':'PRIMARY','family':'RECLAIM_REGIONAL' if regional else 'FROZEN_COARSE_RECLAIM','scope':'RECLAIM_ONLY','feature':None,'cap':None,'availability':False,'body':body,'lookback':lb,'distance':None,'rr':STUDY_RR,'ratio':None,'close':close,'range':0.,'regional':regional}
        rows.append(d);rows.append(dict(d,id='COMBINED__'+cid,kind='COMBINED',scope='PRIMARY_OR_RECLAIM'))
    require(len(rows)==59 and len({d['id'] for d in rows})==59,'Pass10 stream count')
    return rows

DEFINITIONS=study_definitions()
DEFINITION_BY_ID={d['id']:d for d in DEFINITIONS}

def configs():return [(d['id'],d['family'],d['lookback'],d['distance'],d['body'],d['range']) for d in DEFINITIONS]

def anchor_for(cid):
    return next(a for a in FROZEN_ENTRIES if a[0]==DEFINITION_BY_ID[cid]['anchor'])

def anchor_qualifies(f,anchor):
    _,_,l,d,b,r=anchor
    return f['distances'][l]<=d and f['body_atr']>=b and f['range_atr']>=r

def comparator_qualifies(f,comparator):return f.get('exact_engulf',True) and anchor_qualifies(f,comparator) and f['body_ratio']>=.60

def condition_passes(f,d):
    if d['feature'] is None:return True
    v=f[d['feature']]
    return v is not None and (d['availability'] or v<=d['cap'])

def condition_metadata(cid,raw):
    d=DEFINITION_BY_ID[cid]
    return {'anchor':d['anchor'],'conditions_json':json.dumps({'kind':d['kind'],'reclaim_lookback':d['lookback'] if d['kind'] in ('RECLAIM','COMBINED') else None,'body_atr_floor':d['body'],'close_location_floor':d['close'],'strict_low_sweep_and_close_reclaim':d['kind'] in ('RECLAIM','COMBINED'),'primary_bypasses_reclaim':d['kind']=='COMBINED'},sort_keys=True),
            'h4_vol_cap':1.10 if d['kind']=='VOL_COMPARATOR' else None,'daily_vol_cap':None,'condition_scope':d['scope'],'availability_only':False,'body_ratio_floor':d['ratio'],'missing_feature_signals':0,'reward_risk':STUDY_RR,'signal_close_floor':d['close'],'stream_kind':d['kind']}

def study_boundaries(cid):
    d=DEFINITION_BY_ID[cid]
    if not d['regional']:return 'FROZEN_COMPARATOR'
    return ','.join(k for k,v,levels in (('lookback',d['lookback'],RECLAIM_LB),('body_floor',d['body'],RECLAIM_BODY),('close_floor',d['close'],RECLAIM_CLOSE)) if v in (levels[0],levels[-1]))

def comparison_pairs():
    pairs=[('PRIMARY__CONTROL','FREQUENCY__CONTROL','FROZEN_COMPARATOR'),('PRIMARY__CONTROL','HYBRID__H4_VOL_LE_1.1','FROZEN_COMPARATOR')]
    centre=reclaim_id(20,1.25,.80);coarse=reclaim_id(20,.75,.65)
    for d in DEFINITIONS:
        if d['kind']!='RECLAIM':continue
        cid=d['id'];combined='COMBINED__'+cid
        pairs.extend([('PRIMARY__CONTROL',cid,'STANDALONE_VS_PRIMARY'),('PRIMARY__CONTROL',combined,'INCREMENTAL_TO_PRIMARY'),(cid,combined,'CORE_ADDED_TO_RECLAIM'),('FREQUENCY__CONTROL',combined,'VS_OLD_FREQUENCY'),('HYBRID__H4_VOL_LE_1.1',combined,'VS_OLD_VOL_HYBRID')])
        for ref,label in ((centre,'VS_FROZEN_CENTRE'),(coarse,'VS_FROZEN_COARSE')):
            if cid!=ref:pairs.append((ref,cid,label));pairs.append(('COMBINED__'+ref,combined,label))
    for a,b,axis in condition_neighbours():
        if a<b:pairs.append((a,b,'NEIGHBOUR_'+axis))
    require(len(pairs)==358 and len(set(pairs))==358,'Pass10 comparison count')
    return sorted(pairs)

def condition_neighbours():
    for prefix in ('','COMBINED__'):
        for axis,levels in (('lookback',RECLAIM_LB),('body_floor',RECLAIM_BODY),('close_floor',RECLAIM_CLOSE)):
            if axis=='lookback':pairs=[(reclaim_id(a,b,c),reclaim_id(z,b,c)) for a,z in zip(levels,levels[1:]) for b in RECLAIM_BODY for c in RECLAIM_CLOSE]
            elif axis=='body_floor':pairs=[(reclaim_id(l,a,c),reclaim_id(l,z,c)) for a,z in zip(levels,levels[1:]) for l in RECLAIM_LB for c in RECLAIM_CLOSE]
            else:pairs=[(reclaim_id(l,b,a),reclaim_id(l,b,z)) for a,z in zip(levels,levels[1:]) for l in RECLAIM_LB for b in RECLAIM_BODY]
            for a,b in pairs:yield prefix+a,prefix+b,axis;yield prefix+b,prefix+a,axis

def verify_pass9(bars,raw,paths):
    masks,_=independent_mechanism_masks(bars,PASS9_DEFINITIONS);rows=[]
    for d in PASS9_DEFINITIONS:
        ids=[i for i,f in raw.items() if study_qualifies(f,d)]
        require(ids==masks[d['id']],'Independent archived Pass9 mask mismatch '+d['id'])
        for name,pin in PASS9_PINS[d['id']].items():
            a,r,b=replay(ids,paths[name]);sha=digest([core(p) for p in a])
            require(digest(ids)==pin['raw_signal_hash'] and sha==pin['accepted_hash'],'Pinned Pass9 full-ledger mismatch '+d['id']+' '+name)
            require((len(ids),len(a),len(r),len(b))==tuple(int(pin[k]) for k in ('raw_signals','accepted','rejected','blocked')),'Pinned Pass9 counts changed')
            require(abs(sum(p['r'] for p in a if p['r'] is not None)-float(pin['net_r']))<1e-8,'Pinned Pass9 R changed')
            rows.append({'pass9_config':d['id'],'case':name,'raw_signal_hash':digest(ids),'accepted_hash':sha,'accepted':len(a),'parity':'PASS'})
    require(len(rows)==456,'Incomplete Pass9 archive controls')
    return rows

